        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 no longer prepends "Discriminator|"
        // to the Cosmos 'id' property. Existing docs have id = "Blog|<key>".
