        modelBuilder.Entity<Blog>().HasKey(b => b.CosmosId);
        modelBuilder.Entity<Blog>().Property(b => b.CosmosId)
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>().Property(b => b.BlogId)
            .ToJsonProperty("BlogId");

